EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT id, user_id, occurred_at FROM events ORDER BY user_id, occurred_at LIMIT 10

RESET work_mem;
CREATE INDEX ON events (user_id);
